schema.content:
Table "city" {
  "id" INTEGER [pk, not null]
  "city_name" TEXT
}

Table "competitor_event" {
  "event_id" INTEGER
  "competitor_id" INTEGER
  "medal_id" INTEGER
}

Table "event" {
  "id" INTEGER [pk, not null]
  "sport_id" INTEGER
  "event_name" TEXT
}

Table "games" {
  "id" INTEGER [pk, not null]
  "games_year" INTEGER
  "games_name" TEXT
  "season" TEXT
}

Table "games_city" {
  "games_id" INTEGER
  "city_id" INTEGER
}

Table "games_competitor" {
  "id" INTEGER [pk, not null]
  "games_id" INTEGER
  "person_id" INTEGER
  "age" INTEGER
}

Table "medal" {
  "id" INTEGER [pk, not null]
  "medal_name" TEXT
}

Table "noc_region" {
  "id" INTEGER [pk, not null]
  "noc" TEXT
  "region_name" TEXT
}

Table "person" {
  "id" INTEGER [pk, not null]
  "full_name" TEXT
  "gender" TEXT
  "height" INTEGER
  "weight" INTEGER
}

Table "person_region" {
  "person_id" INTEGER
  "region_id" INTEGER
}

Table "sport" {
  "id" INTEGER [pk, not null]
  "sport_name" TEXT
}



Ref: "games_city"."games_id" > "games"."id"

Ref: "games_city"."city_id" > "city"."id"

Ref: "games_competitor"."person_id" > "person"."id"

Ref: "games_competitor"."games_id" > "games"."id"

Ref: "person_region"."region_id" > "noc_region"."id"

Ref: "person_region"."person_id" > "person"."id"

Ref: "event"."sport_id" > "sport"."id"

Ref: "competitor_event"."medal_id" > "medal"."id"

Ref: "competitor_event"."event_id" > "event"."id"

Ref: "competitor_event"."competitor_id" > "games_competitor"."id"
